const d = $input.first().json.body;
function esc(s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const rows = [
  ['Categorie', d.category_label],
  ['Lieu', d.venue],
  ['Ville', d.city],
  ['Adresse', d.address],
  ['Dates', d.dates_label],
  ['Statut', d.status_label],
  ['Lien', d.link],
  ['Description', d.description],
  ['Propose par', (d.submitter_name || '') + (d.submitter_email ? ' <' + d.submitter_email + '>' : '')],
].filter(function (r) { return r[1]; });

const detailsHtml = rows.map(function (r) {
  return '<tr><td style="padding:4px 14px 4px 0;color:#8C8577;font-family:Arial,sans-serif;font-size:0.85em;vertical-align:top;white-space:nowrap;">' + esc(r[0]) + '</td>'
    + '<td style="padding:4px 0;font-family:Arial,sans-serif;font-size:0.92em;">' + esc(r[1]) + '</td></tr>';
}).join('');

const html = '<div style="font-family:Arial,sans-serif;max-width:560px;">'
  + '<h2 style="color:#2E2B27;">Nouvelle proposition d\'evenement</h2>'
  + '<p style="font-size:1.05em;font-weight:bold;">' + esc(d.title) + '</p>'
  + '<table cellpadding="0" cellspacing="0">' + detailsHtml + '</table>'
  + '<p style="margin-top:22px;">'
  + '<a href="' + d.approve_url + '" style="display:inline-block;background:#5F8B7A;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;margin-right:10px;">Valider et publier</a>'
  + '<a href="' + d.reject_url + '" style="display:inline-block;background:#8C8577;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;">Rejeter</a>'
  + '</p>'
  + '<p style="font-size:0.8em;color:#8C8577;margin-top:18px;">Ces liens ouvrent une page de confirmation avant toute action (pas d\'action directe au clic, au cas ou un antivirus de messagerie pre-visite les liens).</p>'
  + '</div>';

return [{ json: { html: html, subject: 'Nouvel evenement a valider : ' + d.title, to: d.to_email } }];
